"import 'package:http/http.dart' as http;
import 'package:flutter/foundation.dart';

class NetworkService {
  /// Pure connectivity check — actually pings the internet.
  /// Returns true only if the device can reach the network right now.
  /// Checks ALL endpoints in parallel for speed — first success wins.
  static Future<bool> isActuallyOnline() async {
    if (kIsWeb) return true;

    // Check all endpoints in parallel — first success returns true immediately
    final endpoints = [
      'https://www.google.com/generate_204',
      'https://clients3.google.com/generate_204',
      'https://connectivitycheck.gstatic.com/generate_204',
      'https://firestore.googleapis.com',
      'https://www.gstatic.com/generate_204',
    ];

    try {
      final result = await Future.any(
        endpoints.map((url) async {
          try {
            final response = await http.get(Uri.parse(url))
                .timeout(const Duration(seconds: 6));
            if (response.statusCode >= 200 && response.statusCode < 400) {
              return true;
            }
          } catch (_) {}
          // If this endpoint failed, return a future that never completes
          // so Future.any picks the first successful one
          return await Future.delayed(const Duration(seconds: 10), () => false);
        }),
      ).timeout(const Duration(seconds: 8), onTimeout: () => false);
      return result;
    } catch (_) {
      return false;
    }
  }
}
"

