+        const launches = inst.launchCount || 0;
+        const firstInstall = inst.firstInstall ? formatTimestamp(inst.firstInstall) : '—';
+        const lastLaunch = inst.lastLaunch ? formatTimestamp(inst.lastLaunch) : '—';
+
+        return `<tr>
+          <td>${i + 1}</td>
