      final nightW = _scanLagnaRange(ssJd, nextSrJd, ayn, planetRashis, guruRashiIdx, allowedLagnas, rules);

      if (mounted) setState(() {
        _dayLagnaWindows = dayW;
        _nightLagnaWindows = nightW;
      });
    } catch (_) {
      if (mounted) setState(() {
        _dayLagnaWindows = [];
        _nightLagnaWindows = [];
